+function attachBlockAnchor(
+	block: AsciidoctorBlock,
+	extracted: AssemblyBlock[],
+): AssemblyBlock[] {
+	const identifier = block.getId?.();
+	if (
+		identifier === undefined ||
+		identifier.length === 0 ||
+		block.getContext() === "section"
+	) {
+		return extracted;
+	}
+
+	return [
+		<AssemblyAnchor>{
+			type: "anchor",
+			identifier,
+			location: getSourceLocation(block),
+		},
+		...extracted,
+	];
+}
